const labels:Record<string,string>={GROUND_STAFF:'With Ground Staff',FINISHING:'Warehouse finishing',FINISHED:'Finished Goods',REPRINTING:'With reprint artist',HANDOFF:'Artisan handoff',RETURN:'Artisan return',REVERSAL:'Reversal',LABEL_CONFIRM:'Label confirmed',ARTIST_TRANSFER:'Artist transfer',GROUND_ISSUE:'Issued to Ground Staff',GROUND_DISPUTE:'Finishing dispute',STOCK_DISPUTE:'Warehouse dispute',REPRINT_OUT:'Out for reprint',REPRINT_RECEIVE:'Reprint received',FINISH_RECEIVE:'Finished goods received',JOBWORK_COMPANY:'Despatched to jobwork company',OFFICE_PENDING:'In office inventory processing',OFFICE_STOCK:'Office inventory submitted',SOLD:'Sold out',FACTORY_RETURN_PENDING:'Return to workshop · factory scan pending',JOBWORK_DISPATCH:'Jobwork company despatch',JOBWORK_DISPUTE_RETURN:'Dispute return from company',OFFICE_VENDOR_INTAKE:'Office vendor intake',OFFICE_LABEL_CONFIRM:'Office label confirmed',OFFICE_SEND:'Sent to office',OFFICE_RECEIVE:'Office inventory submitted',OFFICE_SALE:'Sold out',OFFICE_DISPUTE_RETURN:'Office dispute return',CUSTOMER_DISPUTE_RETURN:'Dispute return from customer',FACTORY_DISPUTE_RECEIVE:'Factory dispute received',DISPUTED:'Disputed',RETURNED_TO_SOURCE:'Returned to source',PREPARED:'Labels prepared',INTAKE:'Inventory entry',SUPPLIER_RETURN:'Source return',DISPUTE:'Dispute',AVAILABLE:'Available',ACCEPTED_WORK:'Work accepted',WITH_ARTISAN:'With artisan',PENDING_LABEL_CONFIRMATION:'Pending label',NEEDS_REWORK:'Needs rework',DAMAGED:'Damaged',EXCEPTION:'Location unknown',IN_HOUSE:'In house',OWN:'Own stock',EXTERNAL:'External',CONFIRMED:'Confirmed',DRAFT:'Draft',OPEN:'Open',CLOSED:'Closed',RESOLVED:'Resolved',VOIDED_BY_REVERSAL:'Reversed',EXPECTED:'Counted',UNEXPECTED:'Unexpected'};
const factoryNav=[{group:'WORKSPACE',items:[['Overview',LayoutDashboard],['Inventory',Package],['Receipts & lots',Layers3],['Label center',ScanLine],['Despatches',Box]]},{group:'ARTISAN WORK',items:[['Handoff',ArrowUpRight],['Returns',ArrowDownLeft],['Artisans',Users],['Warehouse',Package]]},{group:'CONTROL & INSIGHTS',items:[['Stock checks',ClipboardCheck],['Exceptions',TriangleAlert],['Reports',ChartNoAxesCombined]]},{group:'MANAGE',items:[['Companies',Building2],['Thanwalas',Building2],['Product types',Tag],['Settings',Settings]]}];
