function Badge({value}:any){const color=['AVAILABLE','ACCEPTED_WORK','CONFIRMED','COMPLETE','EXPECTED','RESOLVED'].includes(value)?'green':['WITH_ARTISAN','OWN','PARTIALLY_REGISTERED'].includes(value)?'purple':['PENDING_LABEL_CONFIRMATION','NEEDS_REWORK','DRAFT','OPEN'].includes(value)?'amber':['DAMAGED','DISPUTED','EXCEPTION','UNEXPECTED'].includes(value)?'red':'gray';return <span className={'badge '+color}><i/>{display(value)}</span>}
function Empty({title='Nothing here yet',text='Records will appear here as you work.',action}:any){return <div className="empty"><div className="empty-icon"><Package size={26}/></div><h3>{title}</h3><p>{text}</p>{action}</div>}
function Field({label,children,hint}:any){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function universalActions(item:any,can:(permission:string)=>boolean){
 const actions:any[]=[];
 const add=(action:any)=>{if(!action.permission||can(action.permission))actions.push(action)};
 if(item._scanKind==='pending'){
  if(item.journey==='OFFICE')add({id:'officeLabel',title:'Confirm New Office Label',detail:'Attach this outside-vendor barcode, then submit it into office inventory.',icon:CheckCircle2,directOp:'officeLabel',nextView:'Office',nextFilter:'officeSell',permission:'officeLabel'});
  else {
  add({id:'intake',title:'Fresh item entry',detail:'Inspect and add this new label to inventory.',icon:ScanLine,view:'Label center',filter:'intake',permission:'label'});
  add({id:'damage',title:'Incoming damaged item',detail:'Record this new label as damaged stock.',icon:TriangleAlert,view:'Label center',filter:'damage',permission:'label'});
  }
 add({id:'recovery',kind:'recovery',title:'Recover / Replace Barcode',detail:'Verify the saree and replace its label using the same permanent code.',icon:Printer,permission:'recovery'});
  return actions;
 }
 if(item.holder==='JOBWORK_COMPANY')add({id:'jobworkReturn',title:`Return from ${item.company_name||'company'} for dispute`,detail:'Receive it into factory inventory with the dispute reason.',icon:RotateCcw,view:'Despatches',filter:'jobworkReturn',permission:'postFinish',danger:true});
 else if(item.holder==='OFFICE_PENDING')add({id:'officeReceive',title:'Factory Finished Goods Received',detail:'Office Staff submits the scanned product into office inventory.',icon:CheckCircle2,directOp:'officeReceive',nextView:'Office',nextFilter:'officeSell',permission:'officeReceive'});
 else if(item.holder==='OFFICE_STOCK'){
  add({id:'officeSell',title:'Sold Out',detail:'Office Staff marks this confirmed office product as sold.',icon:CheckCircle2,directOp:'officeSell',nextView:'Office',nextFilter:'customerReturn',permission:'officeSell'});
  if(item.journey!=='OFFICE')add({id:'officeReturn',title:'Dispute Return to Workshop',detail:'Send a TaraFabbs workshop-origin dispute back for a separate Factory Staff receipt scan.',icon:RotateCcw,view:'Office',filter:'officeReturn',permission:'officeReturn',danger:true});
 }
 else if(item.holder==='SOLD'&&item.journey!=='OFFICE')add({id:'customerReturn',title:'Dispute Return from Customer',detail:'Send the sold TaraFabbs workshop-origin product back for a separate Factory Staff receipt scan.',icon:RotateCcw,view:'Office',filter:'customerReturn',permission:'officeReturn',danger:true});
 else if(item.holder==='FACTORY_RETURN_PENDING')add({id:'factoryReceive',title:'Receive Return at Factory',detail:'Factory Staff confirms physical receipt, then reprint or Ground Staff becomes available.',icon:ScanLine,view:'Despatches',filter:'factoryReceive',permission:'postFinish'});
 else if(item.holder!=='RETURNED_TO_SOURCE'){
  if(item.holder==='WITH_ARTISAN'){
   if(item.condition==='REPRINTING')add({id:'reprintReceive',title:'Receive Reprint Scan',detail:'Receive and inspect the completed reprint.',icon:ScanLine,view:'Warehouse',filter:'reprintReceive',permission:'reprintReceive'});
   else {
    add({id:'return',title:'Artist Delivery',detail:'Receive and inspect this saree from its current artisan.',icon:ArrowDownLeft,view:'Returns',filter:'ALL',permission:'return'});
    if(!['DAMAGED','DISPUTED'].includes(item.condition))add({id:'dispute',title:'Report artisan dispute',detail:'Record a dispute against the current artisan work.',icon:TriangleAlert,view:'Returns',filter:'dispute',permission:'dispute'});
    if(['AVAILABLE','ACCEPTED_WORK'].includes(item.condition))add({id:'artistTransfer',title:'Transfer to another artist',detail:'Choose the next artist and transfer directly.',icon:MoveUpRight,view:'Warehouse',filter:'artistTransfer',permission:'handoff'});
   }
  }
  if(item.holder==='IN_HOUSE'){
   if(item.condition==='FINISHED'&&item.ownership==='EXTERNAL')add({id:'jobworkDispatch',title:`Despatch to ${item.company_name||'jobwork company'}`,detail:'Remove it from active inventory and record the company, date and time.',icon:Building2,directOp:'jobworkDispatch',nextView:'Despatches',nextFilter:'jobworkReturn',permission:'postFinish'});
   if(item.condition==='FINISHED'&&item.ownership==='OWN')add({id:'officeSend',title:'Send to Office',detail:'Only TaraFabbs own products can enter office inventory processing.',icon:Box,directOp:'officeSend',nextView:'Despatches',nextFilter:'factoryReceive',permission:'postFinish'});
   if(['AVAILABLE','ACCEPTED_WORK','NEEDS_REWORK'].includes(item.condition))add({id:'handoff',title:'Out to Artist',detail:item.condition==='NEEDS_REWORK'?'Choose an artist for the required rework.':'Choose an artist and record the next work.',icon:ArrowUpRight,view:'Handoff',filter:'ALL',permission:'handoff',rework:item.condition==='NEEDS_REWORK'});
   if(['AVAILABLE','ACCEPTED_WORK','DISPUTED'].includes(item.condition))add({id:'groundSend',title:'Scan to Ground Staff',detail:item.condition==='DISPUTED'?'Route this received dispute through warehouse finishing.':'Send this saree to warehouse finishing.',icon:Users,view:'Warehouse',filter:'groundSend',permission:'groundSend'});
   if(!['DAMAGED','DISPUTED','NEEDS_REWORK','PENDING_LABEL_CONFIRMATION'].includes(item.condition))add({id:'stockDispute',title:'Warehouse Damage / Dispute',detail:'Record an in-house damage or dispute finding.',icon:TriangleAlert,view:'Warehouse',filter:'stockDispute',permission:'dispute'});
  }
  if(item.holder==='GROUND_STAFF'){
   add({id:'finishReceive',title:'Finished Goods Received',detail:'Inspect and receive this saree from finishing.',icon:CheckCircle2,view:'Warehouse',filter:'finishReceive',permission:'finishReceive'});
   if(!['DAMAGED','DISPUTED'].includes(item.condition))add({id:'groundDispute',title:'Finishing Damage / Dispute',detail:'Record a finding while it is with Ground Staff.',icon:TriangleAlert,view:'Warehouse',filter:'groundDispute',permission:'dispute'});
  }
  if(['DAMAGED','DISPUTED','NEEDS_REWORK'].includes(item.condition)){
   add({id:'reprintOut',title:'Out Scan for Reprint',detail:'Send this damaged or disputed saree for reprint.',icon:RotateCcw,view:'Warehouse',filter:'reprintOut',permission:'reprintOut',danger:item.condition==='DISPUTED'});
   add({id:'supplierReturn',title:`Return to ${item.ownership==='OWN'?(item.thanwala_name||'Thanwala'):(item.company_name||'Origin')}`,detail:item.ownership==='OWN'?'Return this disputed Own Product to its saved purchase Thanwala.':'Return this disputed jobwork product to its original company.',icon:Building2,view:'Label center',filter:'supplierReturn',permission:'supplierReturn'});
  }
 }
 add({id:'recovery',kind:'recovery',title:'Recover / Replace Barcode',detail:'Verify the saree and replace its label using the same permanent code.',icon:Printer,permission:'recovery'});
 actions.push({id:'history',kind:'history',title:'Barcode History',detail:'View the complete read-only journey of this barcode.',icon:Clock});
 return actions;
}
function UniversalScanner({d,can,onChoose,onRecover,onUndo,busy,initialCode=''}:any){
 const [item,setItem]=useState<any>(null),[recent,setRecent]=useState<any>(null),[error,setError]=useState(''),[unreadable,setUnreadable]=useState(false),[cameraTrigger,setCameraTrigger]=useState(0);const resultRef=useRef<HTMLDivElement>(null);
 const scan=async(code:string)=>{const normalized=code.trim().toUpperCase(),pending=d.generatedLabels.find((p:any)=>p.code===normalized),piece=d.pieces.find((p:any)=>p.code===normalized),record=pending||piece,company=d.companies.find((c:any)=>c.id===record?.company_id),thanwala=d.thanwalas.find((t:any)=>t.id===record?.thanwala_id);setUnreadable(false);setRecent(null);if(pending)setItem({...pending,_scanKind:'pending',company_name:company?.name,thanwala_name:thanwala?.name});else if(piece)setItem({...piece,_scanKind:'piece',company_name:company?.name,thanwala_name:thanwala?.name});else {setItem(null);setError('This barcode is not part of any prepared label or registered inventory record. Check the printed code and try again.');return}setError('');try{const response=await fetch('/api/ledger?recentScan='+encodeURIComponent(normalized),{cache:'no-store'}),data=await response.json();if(response.ok)setRecent(data.recent?{...data.recent,code:normalized}:null)}catch{}}
 useEffect(()=>{if(initialCode)void scan(initialCode)},[initialCode]);
 useEffect(()=>{if(item)resultRef.current?.focus()},[item]);
 const actions=item?universalActions(item,can):[];
 return <div className="universal-scanner"><p className="muted">Scan with USB / Bluetooth, use the camera, or type the piece code. No stock changes until you choose an action and save its required details.</p><ScannerInput onScan={scan} disabled={!!item||busy} cameraTrigger={cameraTrigger} onUnreadable={can('recovery')?()=>{setItem(null);setRecent(null);setError('');setUnreadable(true)}:undefined}/>{unreadable&&can('recovery')?<div className="unreadable-recovery-prompt" role="alert"><span className="unreadable-recovery-icon"><TriangleAlert size={23}/></span><div><b>Barcode could not be read</b><p>The camera could not decode any usable barcode. Recover the original permanent code before doing a stock movement.</p><div className="button-row"><button className="btn primary" disabled={busy} onClick={onRecover}><Printer size={16}/>Open Barcode Recovery</button><button className="btn" disabled={busy} onClick={()=>{setUnreadable(false);setCameraTrigger(value=>value+1)}}><Camera size={16}/>Try camera again</button></div></div></div>:can('recovery')&&<button className="text-btn" disabled={busy} onClick={onRecover}><Printer size={16}/>Barcode damaged or missing? Recover it here</button>}{error&&<div className="form-error" role="alert"><AlertCircle size={16}/>{error}</div>}{item&&<>{recent?.code===item.code&&<div className="recent-scan-card" role="status"><div className="recent-scan-heading"><span><Clock size={18}/></span><div><b>Scanned {recent.minutesAgo===0?'just now':`${recent.minutesAgo} min${recent.minutesAgo===1?'':'s'} ago`}</b><small>{display(recent.type)}{recent.number?` · ${recent.number}`:''}</small></div></div><dl><div><dt>Scanned by</dt><dd>{recent.actor}</dd></div><div><dt>Scan details</dt><dd>{recent.reason||display(recent.type)}</dd></div></dl>{recent.canUndo?<button className="btn danger-button" disabled={busy} onClick={()=>onUndo(recent)}><Trash2 size={15}/>Delete previous scan</button>:<p>This scan is part of a batch, already changed, or cannot be safely deleted here. Open Barcode History for correction details.</p>}</div>}<div className="universal-scan-result" ref={resultRef} tabIndex={-1}><div><small>{item._scanKind==='pending'?'NEW LABEL · NOT YET IN INVENTORY':'REGISTERED BARCODE'}</small><strong className="mono">{item.code}</strong><span>{d.products.find((p:any)=>p.id===item.product_id)?.name||'Product'} · {item.company_name||'Source'}</span></div><div className="universal-result-badges">{item._scanKind==='pending'?<Badge value="PENDING_LABEL_CONFIRMATION"/>:<><Badge value={item.holder}/><Badge value={item.condition}/></>}</div></div><div className="universal-action-heading"><div><h3>Available actions</h3><p>Only actions valid for this barcode and your access are shown.</p></div><button className="btn" disabled={busy} onClick={()=>{setItem(null);setRecent(null);setError('')}}><RotateCcw size={15}/>Scan another</button></div>{actions.length?<div className="universal-action-grid">{actions.map((option:any)=><button key={option.id} className={option.danger?'danger-option':''} disabled={busy} onClick={()=>onChoose(option,item)}><span className="universal-option-icon"><option.icon size={20}/></span><span><b>{option.title}</b><small>{option.detail}</small></span><ChevronRight size={18}/></button>)}</div>:<div className="info-strip">There are no available actions for your current role.</div>}</>}</div>}
function MobileWorkshopHome({d,onNew,onUniversal,onEdit,canEdit,date,onOpenTransaction}:any){
 const lots=[...d.lots].filter((lot:any)=>lot.status!=='DRAFT').sort((a:any,b:any)=>String(b.created_at).localeCompare(String(a.created_at))).slice(0,10);
 return <div className="mobile-workshop-home"><div className="mobile-workshop-intro"><span className="eyebrow">WORKSHOP MOBILE ACCESS</span><h1>What would you like to do?</h1><p>Create a New Entry or scan a saree to see its valid next step and complete history.</p></div><div className="mobile-workshop-actions"><button onClick={onNew}><span><Plus size={24}/></span><b>New Entry</b><small>Create products, reserve barcodes and record the incoming bill.</small><ArrowUpRight size={18}/></button><button onClick={onUniversal}><span><ScanLine size={24}/></span><b>All-in-one Scanner</b><small>Scan a barcode for the next valid action, recovery or history.</small><ArrowUpRight size={18}/></button></div><section className="mobile-entry-history"><div><h2>Recent New Entries</h2><p>Workshop staff may edit for 24 hours. Admin access does not expire.</p></div>{lots.length?<div>{lots.map((lot:any)=>{const editable=canEdit(lot);return <article key={lot.id}><span><b>{lot.reference||lot.number}</b><small>{d.companies.find((c:any)=>c.id===lot.company_id)?.name||'Source'} · {d.products.find((p:any)=>p.id===lot.product_id)?.name||'Product'}</small><small>{date(lot.created_at,true)} · {lot.accepted} labels</small></span><button className="btn" disabled={!editable} title={editable?'Edit this New Entry':'The 24-hour edit window has closed'} onClick={()=>onEdit(lot)}><Pencil size={14}/>{editable?'Edit':'Edit closed'}</button></article>})}</div>:<p className="muted">No New Entry has been created yet.</p>}</section><DailyHistory d={d} onOpen={onOpenTransaction} compact/></div>;
}
function Table({columns,rows,search=true,placeholder='Search records…',right,empty,emptyText,exportName,onRow,pageSize=8}:any){
 const [q,setQ]=useState(''),[page,setPage]=useState(0),[sort,setSort]=useState<any>(null);
 useEffect(()=>setPage(0),[q,rows.length]);
 const indexed=useMemo(()=>rows.map((row:any)=>({row,text:JSON.stringify(row).toLocaleLowerCase()})),[rows]);
 const filtered=useMemo(()=>{const term=q.trim().toLocaleLowerCase();let results=indexed.filter((item:any)=>!term||item.text.includes(term)).map((item:any)=>item.row);if(sort)results=[...results].sort((a:any,b:any)=>String(a[sort.key]??'').localeCompare(String(b[sort.key]??''),undefined,{numeric:true})*sort.dir);return results},[indexed,q,sort]);
 const pages=Math.max(1,Math.ceil(filtered.length/pageSize)),p=Math.min(page,pages-1);
 return <div className="table-block">{(search||right||exportName)&&<div className="table-tools">{search&&<div className="searchbox"><Search size={16}/><input aria-label={placeholder} placeholder={placeholder} value={q} onChange={event=>setQ(event.target.value)}/>{q&&<button className="table-search-clear" aria-label="Clear search" onClick={()=>setQ('')}><X size={15}/></button>}</div>}<div className="table-right">{right}{exportName&&<button className="btn" disabled={!filtered.length} onClick={()=>csv(exportName,filtered)}><Download size={15}/>Export</button>}</div></div>}<div className="table-scroll"><table><thead><tr>{columns.map((c:any)=><th key={c.key} aria-sort={sort?.key===c.key?(sort.dir===1?'ascending':'descending'):undefined}><button onClick={()=>setSort({key:c.key,dir:sort?.key===c.key?-sort.dir:1})} aria-label={c.label?'Sort by '+c.label:'Sort records'}>{c.label}{sort?.key===c.key&&<span>{sort.dir===1?' ↑':' ↓'}</span>}</button></th>)}</tr></thead><tbody>{filtered.slice(p*pageSize,(p+1)*pageSize).map((r:any,i:number)=><tr key={r.id||i} onClick={()=>onRow?.(r)} tabIndex={onRow?0:undefined} aria-label={onRow?'Open details for '+(r.code||r.name||r.number||r.title||'record'):undefined} onKeyDown={event=>{if(onRow&&event.target===event.currentTarget&&['Enter',' '].includes(event.key)){event.preventDefault();onRow(r)}}} className={onRow?'clickable':''}>{columns.map((c:any)=><td key={c.key}>{c.render?c.render(r):r[c.key]}</td>)}</tr>)}</tbody></table></div>{!filtered.length&&<Empty title={empty||'No matching records'} text={q?'Try another search or clear the search field.':emptyText||'Try another filter, or create your first record.'} action={q?<button className="btn" onClick={()=>setQ('')}>Clear search</button>:undefined}/>}<div className="table-foot"><span aria-live="polite">{filtered.length?`${p*pageSize+1}–${Math.min((p+1)*pageSize,filtered.length)} of ${number(filtered.length)}`:'0'} records</span><div><button className="icon-btn" aria-label="Previous page" disabled={p===0} onClick={()=>setPage(p-1)}><ChevronRight className="flip" size={16}/></button><span>{p+1} / {pages}</span><button className="icon-btn" aria-label="Next page" disabled={p>=pages-1} onClick={()=>setPage(p+1)}><ChevronRight size={16}/></button></div></div></div>
}
function DailyHistory({d,onOpen,scope='all',compact=false}:any){
 const timezone=d.settings.timezone||'Asia/Kolkata',today=new Date().toLocaleDateString('en-CA',{timeZone:timezone}),[selectedDay,setSelectedDay]=useState(today);
 const history=useMemo(()=>{const byDay=new Map<string,any[]>(),formatter=new Intl.DateTimeFormat('en-CA',{timeZone:timezone,year:'numeric',month:'2-digit',day:'2-digit'});for(const transaction of d.transactions){if(scope==='office'&&!officeHistoryTypes.has(transaction.type))continue;const day=formatter.format(new Date(transaction.created_at)),existing=byDay.get(day);if(existing)existing.push(transaction);else byDay.set(day,[transaction])}return {byDay,days:[...byDay.keys()].sort((a,b)=>b.localeCompare(a))}},[d.transactions,scope,timezone]);
 const rows=useMemo(()=>(history.byDay.get(selectedDay)||[]).map((transaction:any)=>{let pieces=0;try{const value=JSON.parse(transaction.snapshot||'[]');pieces=Array.isArray(value)?value.length:0}catch{}return {...transaction,pieces}}),[history,selectedDay]),pieceCount=rows.reduce((sum:number,row:any)=>sum+row.pieces,0),staffCount=new Set(rows.map((row:any)=>row.actor).filter(Boolean)).size,latestDay=history.days[0];
 const shiftDay=(amount:number)=>{const [year,month,day]=selectedDay.split('-').map(Number),next=new Date(Date.UTC(year,month-1,day+amount));setSelectedDay(next.toISOString().slice(0,10))};
 const activity=(type:string)=>{const value=display(type);return value.includes('_')?value.toLowerCase().replaceAll('_',' ').replace(/^./,letter=>letter.toUpperCase()):value};
 return <section className={'panel daily-history-panel '+(compact?'compact':'')}><div className="panel-heading"><div><span className="history-title-icon"><CalendarDays size={18}/></span><h2>Day-by-day history</h2><p>{scope==='office'?'Office journey only · workshop and artisan records stay private.':'Choose a date to review every recorded movement from that day.'}</p></div><div className="daily-history-controls"><button className="icon-btn" aria-label="Previous day" onClick={()=>shiftDay(-1)}><ChevronRight className="flip" size={17}/></button><input aria-label="History date" type="date" value={selectedDay} max={today} onChange={event=>setSelectedDay(event.target.value)}/><button className="icon-btn" aria-label="Next day" disabled={selectedDay>=today} onClick={()=>shiftDay(1)}><ChevronRight size={17}/></button><button className="btn" disabled={selectedDay===today} onClick={()=>setSelectedDay(today)}>Today</button>{latestDay&&latestDay!==selectedDay&&<button className="text-btn" onClick={()=>setSelectedDay(latestDay)}>Latest activity</button>}</div></div><div className="daily-history-summary"><div><span>Movements</span><b>{number(rows.length)}</b></div><div><span>Pieces moved</span><b>{number(pieceCount)}</b></div><div><span>Team members</span><b>{number(staffCount)}</b></div></div><Table key={selectedDay} rows={rows} search={false} pageSize={compact?5:8} empty="No activity on this date" emptyText="Choose another date to review its complete history." exportName={`Daily history · ${selectedDay}`} onRow={onOpen} columns={[{key:'created_at',label:'Time',render:(row:any)=>new Date(row.created_at).toLocaleTimeString('en-IN',{timeZone:timezone,hour:'2-digit',minute:'2-digit'})},{key:'type',label:'Activity',render:(row:any)=><div className="cell-title">{activity(row.type)}<small>{row.reason||'Recorded movement'}</small></div>},{key:'number',label:'Reference',render:(row:any)=><span className="mono ink">{row.number||'—'}</span>},{key:'pieces',label:'Pieces'},{key:'actor',label:'Staff'},{key:'status',label:'Status',render:(row:any)=><Badge value={row.status}/>} ,...(onOpen?[{key:'details',label:'',render:(row:any)=><button className="text-btn" onClick={(event:any)=>{event.stopPropagation();onOpen(row)}}>Details<ChevronRight size={14}/></button>}]:[])]} /></section>;
}
