async function action(op:string,data:any,done?:(r:any)=>void,key?:string){if(preview){setModal({type:'start'});return;}if(!navigator.onLine){notify('You are offline. Reconnect before saving a movement.',true);return null}setBusy(true);setError('');try{const r=await fetch('/api/ledger',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({op,data,key:key||crypto.randomUUID()})}),j:any=await r.json();if(!r.ok)throw Error(j.error);if(j.workspace)setLive(j.workspace);else await refresh();notify('Saved. Your inventory is up to date.');done?.(j);return j;}catch(e:any){setError(e.message);notify(e.message,true);return null;}finally{setBusy(false);}}
