async function chooseUniversalAction(option:any,item:any){if(option.kind==='recovery'){openRecovery(item.code);return}if(option.kind==='history'){openPiece(item);return}if(option.directOp){openForm('confirmMovement',{option,item,key:crypto.randomUUID()});return}setMobileFlow(true);setQueuedScan({code:item.code,view:option.view,filter:option.filter,artisanId:item.artisan_id||'',fromArtistId:option.id==='artistTransfer'?item.artisan_id||'':'',rework:!!option.rework});setModal(null);go(option.view,option.filter)}
